// BigInt-safe bounded prefix sum implementation
// Returns the exact sum only when every prefix sum (including initial 0) is within [bound, bound].
// Rejects negative bounds and arithmetic overflow.

const BigInt = require('bigint');

function boundedPrefixSum(values, bound) {
  if (typeof bound !== 'number' || !Number.isFinite(bound)) {
    return null;
  }

  const boundBig = BigInt(bound);
  if (boundBig < 0n) {
    return null;
  }

  let currentSum = BigInt(0);
  let success = true;

  for (const val of values) {
    const valBig = BigInt(val);
    currentSum = currentSum + valBig;

    if (currentSum < boundBig || currentSum > boundBig) {
      success = false;
      break;
    }
  }

  return success ? currentSum : null;
}

module.exports.boundedPrefixSum = boundedPrefixSum;

